/* ═══════════════════════════════════════════════════════════
   SPELERSKAART
   Een kaart in de stijl van een voetbalspel, maar met een eigen
   ontwerp en de kleuren van de club — niet die van een uitgever.
   De zes waarden en het eindcijfer komen uit de skills die je
   toch al bijhoudt, dus een nieuw rapport verandert de kaart mee.
═══════════════════════════════════════════════════════════ */

/* Hoe zwaar telt elke categorie mee voor het eindcijfer? Losjes
   gebaseerd op hoe voetbalspellen het doen: een spits wordt niet
   afgerekend op verdedigen, een verdediger niet op afwerken. */
const KAART_WEGING = {
  Keeper:       {keeping:0.75, physical:0.25},
  Verdediger:   {pace:0.14, shooting:0.03, passing:0.14, dribbling:0.10, defending:0.40, physical:0.19},
  Middenvelder: {pace:0.14, shooting:0.18, passing:0.30, dribbling:0.22, defending:0.09, physical:0.07},
  Aanvaller:    {pace:0.22, shooting:0.36, passing:0.14, dribbling:0.22, defending:0.01, physical:0.05}
};
/* Kaartsoorten: hoe hoger het cijfer, hoe mooier de kaart */
const KAART_SOORTEN = [
  {vanaf:85, id:"goud",   label:"Goud",   boven:"#f5d67b", onder:"#c9a227", tekst:"#3a2c05", rand:"#a8871c"},
  {vanaf:70, id:"zilver", label:"Zilver", boven:"#e3e7ec", onder:"#a8b0ba", tekst:"#26303a", rand:"#8d959f"},
  {vanaf:0,  id:"brons",  label:"Brons",  boven:"#e0b088", onder:"#a9713f", tekst:"#33200f", rand:"#8d5c33"}
];
function kaartSoort(cijfer) {
  return KAART_SOORTEN.filter(function(k){ return (cijfer||0) >= k.vanaf; })[0] || KAART_SOORTEN[2];
}
/* De zes vakken op de kaart. Staat er een handmatige waarde in
   `speler.htk`, dan wint die van het cijfer uit de rapporten — zo kun
   je een seizoenskaart of een cadeautje precies maken zoals je wilt. */
function kaartWaarden(speler) {
  var eigen = (speler && speler.htk) || {};
  return fcCategorieen(speler).map(function(cat){
    var uitSkills = fcCategorieWaarde(speler, cat);
    var handmatig = Number(eigen[cat.id]);
    var metHand = !isNaN(handmatig) && handmatig > 0;
    return {
      id: cat.id, kort: cat.kort, label: cat.label,
      waarde: metHand ? Math.max(1, Math.min(99, Math.round(handmatig))) : uitSkills,
      uitSkills: uitSkills,
      handmatig: metHand
    };
  });
}
/* Is er ergens met de hand ingegrepen? */
function kaartHandmatig(speler) {
  return kaartWaarden(speler).some(function(w){ return w.handmatig; });
}
/* Het eindcijfer mag ook met de hand, los van de zes vakken */
function kaartEigenCijfer(speler) {
  var v = Number((speler && speler.htk && speler.htk.totaal));
  return (!isNaN(v) && v > 0) ? Math.max(1, Math.min(99, Math.round(v))) : null;
}
/* Het eindcijfer. Categorieën die nog niet ingevuld zijn tellen niet
   mee, en de weging wordt over de rest verdeeld — anders zakt iemand
   naar 40 alleen omdat je zijn fysiek nog niet hebt beoordeeld. */
function kaartCijfer(speler) {
  var eigen = kaartEigenCijfer(speler);
  if (eigen !== null) return eigen;
  var weging = KAART_WEGING[speler && speler.positie] || KAART_WEGING.Middenvelder;
  var som = 0, gewicht = 0;
  kaartWaarden(speler).forEach(function(w){
    var g = weging[w.id];
    if (!g || w.waarde === null) return;
    som += w.waarde * g; gewicht += g;
  });
  if (!gewicht) return null;
  return Math.max(1, Math.min(99, Math.round(som / gewicht)));
}
/* De afkorting op de kaart: liever de rol uit de opstelling dan
   alleen "Middenvelder". */
function kaartPositie(speler) {
  var kort = {Keeper:"KP", Verdediger:"VD", Middenvelder:"MV", Aanvaller:"AV"};
  return kort[speler && speler.positie] || "SP";
}
function kaartCompleet(speler) {
  var w = kaartWaarden(speler);
  return w.filter(function(x){ return x.waarde !== null; }).length + "/" + w.length;
}

/* ═══════════════════════════════════════════════════════════
   IN MIJN AGENDA
   Een agendabestand van één gebeurtenis, zodat spelers en ouders
   hem in hun eigen agenda kunnen zetten. Het formaat is streng:
   regels langer dan 75 tekens moeten gevouwen worden en komma's,
   puntkomma's en backslashes moeten ontsnapt.
═══════════════════════════════════════════════════════════ */
function icsOntsnap(t) {
  return String(t == null ? "" : t)
    .replace(/\\/g, "\\\\")
    .replace(/;/g, "\\;")
    .replace(/,/g, "\\,")
    .replace(/\r?\n/g, "\\n");
}
/* Regels van maximaal 75 tekens; het vervolg begint met een spatie */
function icsVouw(regel) {
  if (regel.length <= 75) return regel;
  var uit = [regel.slice(0, 75)], rest = regel.slice(75);
  while (rest.length > 74) { uit.push(" " + rest.slice(0, 74)); rest = rest.slice(74); }
  if (rest.length) uit.push(" " + rest);
  return uit.join("\r\n");
}
/* Datum en tijd als lokale tijd, zonder tijdzone: dan neemt de agenda
   van de ontvanger gewoon de tijd over die er staat. */
function icsStempel(datum, tijd) {
  var d = parseerDatum(datum);
  if (!d) return null;
  var uur = 12, min = 0;
  if (tijd && /^\d{1,2}:\d{2}$/.test(tijd)) {
    var delen = tijd.split(":");
    uur = Number(delen[0]); min = Number(delen[1]);
  }
  function tw(n){ return (n<10?"0":"")+n; }
  return d.getFullYear() + tw(d.getMonth()+1) + tw(d.getDate()) +
         "T" + tw(uur) + tw(min) + "00";
}
/* Zoveel minuten optellen bij een stempel */
function icsPlus(stempel, minuten) {
  if (!stempel) return null;
  var d = new Date(
    Number(stempel.slice(0,4)), Number(stempel.slice(4,6))-1, Number(stempel.slice(6,8)),
    Number(stempel.slice(9,11)), Number(stempel.slice(11,13)));
  d.setMinutes(d.getMinutes() + minuten);
  function tw(n){ return (n<10?"0":"")+n; }
  return d.getFullYear() + tw(d.getMonth()+1) + tw(d.getDate()) +
         "T" + tw(d.getHours()) + tw(d.getMinutes()) + "00";
}
/* g = {titel, datum, tijd, duur (minuten), locatie, uitleg, id} */
function maakICS(g) {
  var begin = icsStempel(g.datum, g.tijd);
  if (!begin) return null;
  var eind = icsPlus(begin, Number(g.duur) || 90);
  var nu = new Date();
  function tw(n){ return (n<10?"0":"")+n; }
  var gemaakt = nu.getUTCFullYear() + tw(nu.getUTCMonth()+1) + tw(nu.getUTCDate()) +
                "T" + tw(nu.getUTCHours()) + tw(nu.getUTCMinutes()) + tw(nu.getUTCSeconds()) + "Z";
  var regels = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//" + ONTWERPER.studio + "//" + teamNaamVol() + "//NL",
    "CALSCALE:GREGORIAN",
    "METHOD:PUBLISH",
    "BEGIN:VEVENT",
    "UID:" + (g.id || Date.now()) + "@fc-harlingen",
    "DTSTAMP:" + gemaakt,
    "DTSTART:" + begin,
    "DTEND:" + eind,
    "SUMMARY:" + icsOntsnap(g.titel)
  ];
  if (g.locatie)  regels.push("LOCATION:" + icsOntsnap(g.locatie));
  if (g.uitleg)   regels.push("DESCRIPTION:" + icsOntsnap(g.uitleg));
  if (g.heleDag !== true) {
    /* Een uur van tevoren een seintje */
    regels.push("BEGIN:VALARM", "TRIGGER:-PT60M", "ACTION:DISPLAY",
                "DESCRIPTION:" + icsOntsnap(g.titel), "END:VALARM");
  }
  regels.push("END:VEVENT", "END:VCALENDAR");
  return regels.map(icsVouw).join("\r\n") + "\r\n";
}
function deelICS(g) {
  var tekst = maakICS(g);
  if (!tekst) { meldFout("Deze gebeurtenis heeft nog geen datum."); return; }
  var naam = String(g.titel || "afspraak").replace(/[^a-z0-9]/gi, "-")
    .replace(/-+/g, "-").replace(/^-|-$/g, "").toLowerCase() + ".ics";
  var blob = new Blob([tekst], {type:"text/calendar;charset=utf-8"});
  deelOfDownload(blob, naam, g.titel, function(hoe){
    meldGoed(hoe === "gedeeld" ? "Afspraak gedeeld" : "Opgeslagen als " + naam + " in Downloads");
  });
}

/* ═══════════════════════════════════════════════════════════
   VERJAARDAGEN
   Uit de geboortedatum van de spelers, dus je hoeft ze niet zelf
   in te voeren. Ze verschijnen elk jaar opnieuw.
═══════════════════════════════════════════════════════════ */
function verjaardagenIn(spelers, jaar) {
  return (spelers||[]).map(function(s){
    var d = parseerDatum(s.geboortedatum);
    if (!d) return null;
    function tw(n){ return (n<10?"0":"")+n; }
    var datum = jaar + "-" + tw(d.getMonth()+1) + "-" + tw(d.getDate());
    return {
      id: "vj-" + s.id + "-" + jaar,
      spelerId: s.id,
      naam: s.naam,
      datum: datum,
      wordt: jaar - d.getFullYear(),
      titel: s.naam + " wordt " + (jaar - d.getFullYear())
    };
  }).filter(Boolean).sort(function(a,b){ return a.datum.localeCompare(b.datum); });
}
/* Wie is er jarig op deze dag? */
function verjaardagenOp(spelers, datum) {
  var d = parseerDatum(datum);
  if (!d) return [];
  return verjaardagenIn(spelers, d.getFullYear()).filter(function(v){ return v.datum===datum; });
}
/* De eerstvolgende verjaardagen vanaf vandaag, over de jaargrens heen */
function komendeVerjaardagen(spelers, vanaf, aantal) {
  var start = parseerDatum(vanaf) || new Date();
  var lijst = verjaardagenIn(spelers, start.getFullYear())
    .concat(verjaardagenIn(spelers, start.getFullYear()+1));
  var vandaagStr = vanaf || "";
  return lijst.filter(function(v){ return v.datum >= vandaagStr; }).slice(0, aantal || 5);
}

